package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ai_query_audits") public class AiQueryAudit{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(nullable=false) private String actor;@Column(name="customer_id") private UUID customerId;@Column(nullable=false,length=1000) private String question;@Column(name="answer_summary",nullable=false,columnDefinition="TEXT") private String answerSummary;@Column(nullable=false,length=60) private String intent;@Column(name="created_at",nullable=false) private Instant createdAt;@PrePersist void create(){createdAt=Instant.now();}public UUID getId(){return id;}public String getActor(){return actor;}public void setActor(String v){actor=v;}public UUID getCustomerId(){return customerId;}public void setCustomerId(UUID v){customerId=v;}public String getQuestion(){return question;}public void setQuestion(String v){question=v;}public String getAnswerSummary(){return answerSummary;}public void setAnswerSummary(String v){answerSummary=v;}public String getIntent(){return intent;}public void setIntent(String v){intent=v;}public Instant getCreatedAt(){return createdAt;}}
